def _feat(src):
    words = src.split()
    toks = set(words)
    dense = "".join(words)
    return len(dense), len(toks), dense.count("(")


def score(program: str) -> float:
    size, vocab, calls = _feat(program)
    raw = size * 7 + vocab * 13 + calls * 29
    return raw / (raw + 40000)

def score(program: str) -> float:
    import ast
    tree = ast.parse(program)
    nodes = list(ast.walk(tree))
    kinds = {type(n).__name__ for n in nodes}
    subtrees = {ast.dump(n) for n in nodes}
    a = min(len(kinds), 30) / 30
    b = len(subtrees) / len(nodes)
    return (a + b) / 2

import zlib
def score(program: str) -> float:
    h = lambda s: zlib.crc32(s.encode()) / 2 ** 32
    t = program.split() or ["x"]
    return 0.35 * h(" ".join(t[:3])) + 0.35 * h(max(t, key=len)) + 0.3 * sum(map(h, t)) / len(t)

def score(program: str) -> float:
    import ast
    try:
        t = ast.parse(program)
        w = list(ast.walk(t))
        n = len(w)
        c = sum(isinstance(x, (ast.If, ast.For, ast.While)) for x in w)
        return 0.4 + min(0.4, n/200) + min(0.2, c/20)
    except:
        return 0.0

